<script setup lang="ts">
import {computed,ref,watch,nextTick,onMounted} from 'vue';
import {useEditorBoundary,useEditorDraft,useFormFeedback} from './editorGuard';
import {request} from './model';import type {State,DeviceLink,Device} from './model';
const props=defineProps<{state:State;projectId:string;networkId?:string;initial:DeviceLink}>();const emit=defineEmits<{saved:[state:State];busy:[value:boolean];remove:[link:DeviceLink]}>();
const root=ref<HTMLElement>(),form=ref<HTMLFormElement>(),sourceQuery=ref(''),targetQuery=ref(''),draft=ref<DeviceLink>(JSON.parse(JSON.stringify(props.initial))),busy=ref(false),error=ref(''),extras=ref(!!props.initial.id);
const revision=props.state.revision,guard=useEditorDraft(()=>draft.value,()=>busy.value);useEditorBoundary(root,()=>busy.value);useFormFeedback(root,()=>error.value);
const devices=computed(()=>props.state.devices.filter(d=>props.state.modules.some(m=>m.id===d.moduleId&&props.state.sites.some(s=>s.id===m.siteId&&s.projectId===props.projectId))));
const matches=(d:Device,q:string)=>[d.name,d.assetTag,props.state.models.find(m=>m.id===d.modelId)?.name].join(' ').toLowerCase().includes(q.toLowerCase());
const sources=computed(()=>devices.value.filter(d=>d.id===draft.value.sourceId||matches(d,sourceQuery.value))),targets=computed(()=>devices.value.filter(d=>d.id!==draft.value.sourceId&&(d.id===draft.value.targetId||matches(d,targetQuery.value))));
const eligible=computed(()=>props.state.networks.filter(n=>n.projectId===props.projectId&&n.deviceIds.includes(draft.value.sourceId)&&n.deviceIds.includes(draft.value.targetId)));
watch([()=>draft.value.sourceId,()=>draft.value.targetId],()=>{draft.value.networkIds=draft.value.networkIds.filter(id=>eligible.value.some(n=>n.id===id));if(!props.initial.id&&props.networkId&&eligible.value.some(n=>n.id===props.networkId)&&!draft.value.networkIds.includes(props.networkId))draft.value.networkIds.push(props.networkId)});
watch(()=>draft.value.sourceId,id=>{if(id===draft.value.targetId)draft.value.targetId=''});
const duplicate=computed(()=>props.state.links.find(l=>l.id!==draft.value.id&&l.kind===draft.value.kind&&(l.sourceId===draft.value.sourceId&&l.targetId===draft.value.targetId||l.sourceId===draft.value.targetId&&l.targetId===draft.value.sourceId)&&draft.value.kind==='logical'));
async function save(){if(busy.value)return;error.value='';if(duplicate.value){error.value='这两台设备已有逻辑关系，请编辑已有链路';return}if(draft.value.status==='confirmed'&&draft.value.kind==='physical'&&(!draft.value.sourcePort.trim()||!draft.value.targetPort.trim())){error.value='确认物理链路前请填写两端端口，或先以“待确认”保存';return}busy.value=true;emit('busy',true);try{const next=await request<State>('/links'+(draft.value.id?'/'+draft.value.id:''),draft.value.id?'PUT':'POST',{revision,link:draft.value});guard.accept();emit('saved',next)}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false)}}
function saveShortcut(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(!busy.value)form.value?.requestSubmit()}}
onMounted(()=>nextTick(()=>root.value?.querySelector<HTMLSelectElement>('select')?.focus()));
</script>
<template><section ref="root" class="link-quick-editor" @keydown="saveShortcut"><form ref="form" @submit.prevent="save"><fieldset class="editor-fieldset" :disabled="busy"><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="link-type-choice"><label :class="{active:draft.kind==='physical'}"><input v-model="draft.kind" type="radio" value="physical" name="link-kind" aria-label="物理连接"/><strong>物理连接</strong><small>记录一条实际线缆，可填写两端端口</small></label><label :class="{active:draft.kind==='logical'}"><input v-model="draft.kind" type="radio" value="logical" name="link-kind" aria-label="逻辑关系"/><strong>逻辑关系</strong><small>记录设备关系，不表示实际接线</small></label></div><div class="link-endpoints"><section><h3>端点 A</h3><label>查找设备<input v-model="sourceQuery" aria-label="查找端点A" placeholder="名称、资产编号或型号…" autocomplete="off"/></label><label>设备<select v-model="draft.sourceId" aria-label="端点A设备" required><option value="" disabled>选择第一台设备</option><option v-for="d in sources" :key="d.id" :value="d.id">{{d.name}} · {{d.assetTag}}</option></select></label><label v-if="draft.kind==='physical'">端口<input v-model="draft.sourcePort" aria-label="端点 A 端口" maxlength="80" name="sourcePort" spellcheck="false" autocomplete="off" placeholder="如 Ethernet1/1，可稍后补充"/></label></section><section><h3>端点 B</h3><label>查找设备<input v-model="targetQuery" aria-label="查找端点B" placeholder="名称、资产编号或型号…" autocomplete="off"/></label><label>设备<select v-model="draft.targetId" aria-label="端点B设备" required><option value="" disabled>选择第二台设备</option><option v-for="d in targets" :key="d.id" :value="d.id">{{d.name}} · {{d.assetTag}}</option></select></label><label v-if="draft.kind==='physical'">端口<input v-model="draft.targetPort" aria-label="端点 B 端口" maxlength="80" name="targetPort" spellcheck="false" autocomplete="off" placeholder="如 eth0，可稍后补充"/></label></section></div><label class="link-status">确认状态<select v-model="draft.status" aria-label="连接确认状态"><option value="pending">待确认 · 先记录，后核实</option><option value="confirmed">已确认</option></select></label><details :open="extras" class="link-optional"><summary>补充网络、速率与备注（可选）</summary><div class="form-grid"><label>介质<input v-model="draft.medium" aria-label="介质" maxlength="80" placeholder="光纤 / 铜缆"/></label><label>速率 Gbps<input v-model.number="draft.speedGbps" aria-label="速率 Gbps" required type="number" min="0" max="100000" step="any"/></label></div><fieldset class="link-network-choice"><legend>承载网络</legend><label v-for="n in eligible" :key="n.id" class="checkbox-label"><input v-model="draft.networkIds" type="checkbox" :value="n.id" :aria-label="'承载网络 '+n.name"/>{{n.name}}</label><p v-if="!eligible.length">两端没有共同网络，可先保存链路，之后再补归属。</p></fieldset><label>连接备注<textarea v-model="draft.note" rows="2" maxlength="2000"/></label></details><div class="modal-actions"><button v-if="draft.id" type="button" class="text-button danger-text" :disabled="busy" @click="guard.accept();emit('remove',draft)">删除此链路</button><span v-else class="muted small">记录保存后不会下发设备配置</span><button class="primary" :disabled="busy">{{busy?'正在保存…':'保存设备链路'}}</button></div></fieldset></form></section></template>
